// A final test at the end of every level (HTML, CSS and JavaScript Basic and Intermediate; Python Basic, Intermediate
// and Advanced; React Basic and Intermediate): 20 quick questions across the whole level, scored with stars and a badge like a Module Challenge.
// The first option of each question is the right one (the app shuffles them). Checked in lessonV5.test.ts.
import type { Lesson, Level, SkillKey, Unit } from '../types';
import { mcq } from './htmlV5/kit';

type Q = [prompt: string, options: [string, ...string[]], why: string, mono?: boolean];

const finalTest = (id: string, name: string, skill: SkillKey, level: Level, learned: [string, string, string], qs: Q[]): Lesson => ({
  id,
  title: `Final test: ${name}`,
  kind: 'lesson',
  format: 'v5',
  exam: true,
  level,
  minutes: 10,
  skill,
  badge: { icon: '🎓', name },
  learned,
  steps: qs.map(([prompt, options, why, mono], i) => ({ ...mcq(i + 1, prompt, options, why, { mono }), kicker: `FINAL TEST · QUESTION ${i + 1} OF ${qs.length}` })),
});

/** The unit that holds a level's final test, shown after the level's last module. */
export const testUnit = (t: Lesson): Unit => ({ id: `${t.id}-u`, title: 'Final test', lessons: [{ id: t.id, title: t.title, meta: `Final test · ${t.steps.length} questions` }] });

